    rows=list(csv.DictReader((PREV/'metrics/iter_01_CORRESPONDENCES.csv').open()));a=np.load(PREV/'local_results/INITIAL/FIELD.npz');V=a['V'];F=a['F'];out=[];face_errors=[]
